begin;
create extension if not exists pgtap with schema extensions;
select plan(41);
insert into auth.users(id) values ('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222'),('33333333-3333-4333-8333-333333333333'),('44444444-4444-4444-8444-444444444444');
insert into private.moderators values('33333333-3333-4333-8333-333333333333');
insert into public.chat_rooms(id,name,created_by) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Private test','11111111-1111-4111-8111-111111111111');
insert into public.chat_members values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$insert into public.profiles(id,display_name,home_lat,home_lng) values(auth.uid(),'Test',52.2,5.4)$$,'Own profile');
select throws_ok($$insert into public.profiles(id,display_name) values('22222222-2222-4222-8222-222222222222','Impersonation')$$,'42501',null,'Cannot impersonate profile');
select lives_ok($$insert into public.reports(id,user_id,author_name,type,text,lat,lng) values('test-point',auth.uid(),'Test','danger','Test only',52.2,5.4)$$,'Create report');
select is((select extensions.st_x(geom) from public.reports where id='test-point'),5.4::double precision,'Longitude is X');
select lives_ok($$insert into public.reports(id,user_id,author_name,type,text,lat,lng,geometry_type,polygon) values('test-polygon',auth.uid(),'Test','danger','Polygon',52.2,5.4,'polygon','[[52.2,5.4],[52.3,5.4],[52.3,5.5]]')$$,'Leaflet polygon accepted');
select throws_ok($$insert into public.reports(id,user_id,author_name,type,text,lat,lng,geometry_type,polygon) values('bad-polygon',auth.uid(),'Test','danger','Bad',52.2,5.4,'polygon','[[95,5.4],[52.3,5.4],[52.3,5.5]]')$$,'P0001','Coordinate out of range','Invalid geometry rejected');
select throws_ok($$update public.reports set status='hidden' where id='test-point'$$,'42501',null,'Owner cannot moderate directly');
select throws_ok($$select public.moderate_report('test-point','hidden','No')$$,'42501','Moderator required','RPC checks moderator');
select lives_ok($$insert into public.reports(id,user_id,author_name,type,text,lat,lng) values('test-owner-lifecycle',auth.uid(),'Test','danger','Owner lifecycle',52.2,5.4)$$,'Create owner lifecycle report');
select lives_ok($$select public.set_own_report_status('test-owner-lifecycle','hidden')$$,'Owner can hide own report through lifecycle RPC');
select is((select status from public.reports where id='test-owner-lifecycle'),'hidden','Owner lifecycle status persisted');
select lives_ok($$insert into public.chat_messages(room_id,user_id,body) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',auth.uid(),'Private')$$,'Member sends chat');
select lives_ok($$insert into public.push_subscriptions(user_id,endpoint,p256dh,auth) values(auth.uid(),'https://push.example.test/1','test-key','test-auth')$$,'Own push subscription');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from public.profiles),0::bigint,'Home location private');
select is((select count(*) from public.reports),2::bigint,'Second user sees active reports');
select is((select count(*) from public.chat_messages),0::bigint,'Nonmember cannot read chat');
select is((select count(*) from public.push_subscriptions),0::bigint,'Push endpoints private');
select throws_ok($$insert into public.chat_members(room_id,user_id) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',auth.uid())$$,'42501',null,'Cannot self-enrol');
select throws_ok($$insert into public.chat_messages(room_id,user_id,body) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',auth.uid(),'Intrusion')$$,'42501',null,'Nonmember cannot send');
select throws_ok($$insert into public.reports(id,user_id,author_name,type,text,lat,lng) values('spoof','11111111-1111-4111-8111-111111111111','Fake','danger','Bad',52,5)$$,'42501',null,'Cannot spoof report owner');
select throws_ok($$select public.set_own_report_status('test-point','hidden')$$,'42501','Report not found or not owner','Non-owner cannot change owner report through lifecycle RPC');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select lives_ok($$select public.moderate_report('test-point','hidden','Test moderation')$$,'Moderator hides report');
select is((select count(*) from public.moderation_actions),1::bigint,'Audit action recorded');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from public.reports where id='test-point'),0::bigint,'Hidden report inaccessible to other users');
select is((select count(*) from public.moderation_actions),0::bigint,'Moderation audit private');
-- Private and group chat: guests cannot start conversations, members only can read and write.
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated","is_anonymous":false}',true);
select lives_ok($pg$insert into public.profiles(id,display_name,discoverable) values(auth.uid(),'Buren B',true)$pg$,'User B explicitly opts in');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","is_anonymous":false}',true);
select lives_ok($pg$insert into public.profiles(id,display_name,discoverable) values(auth.uid(),'Buren C',true)$pg$,'User C explicitly opts in');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated","is_anonymous":true}',true);
select throws_ok($pg$select public.set_profile_discoverability(true,'Bowie','🐶','Nijkerk','Labrador')$pg$,'42501','A verified account is required','Anonymous profile cannot opt in through RPC');
select throws_ok($pg$update public.profiles set discoverable=true where id=auth.uid()$pg$,'42501','Verified account required for profile discoverability','Anonymous user cannot bypass RPC through direct profile update');
select throws_ok($pg$select public.start_private_chat('22222222-2222-4222-8222-222222222222')$pg$,'42501','Verified account required','Anonymous user cannot create a private conversation');
select throws_ok($pg$select public.start_group_chat('Wandelen',array['22222222-2222-4222-8222-222222222222'::uuid,'33333333-3333-4333-8333-333333333333'::uuid])$pg$,'42501','Verified account required','Anonymous user cannot create a group');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated","is_anonymous":false}',true);
select lives_ok($pg$select public.set_profile_discoverability(true,'Bowie','🐶','Nijkerk','Labrador')$pg$,'Verified user can explicitly opt in');
select is((select discoverable from public.profiles where id=auth.uid()),true,'Verified opt-in is stored and confirmed');
select lives_ok($pg$select public.start_group_chat('Wandelen',array['22222222-2222-4222-8222-222222222222'::uuid,'33333333-3333-4333-8333-333333333333'::uuid])$pg$,'Verified user can create an opt-in group');
select is((select count(*) from public.chat_members where room_id=(select id from public.chat_rooms where name='Wandelen')),3::bigint,'Created group has exactly three members');
select lives_ok($pg$select public.start_group_chat('Samen wandelen',array['22222222-2222-4222-8222-222222222222'::uuid])$pg$,'Two verified accounts can create a named group');
select is((select count(*) from public.chat_members where room_id=(select id from public.chat_rooms where name='Samen wandelen')),2::bigint,'Two-account group has exactly two members');
select throws_ok($pg$select public.start_group_chat('Duplicate',array['22222222-2222-4222-8222-222222222222'::uuid,'22222222-2222-4222-8222-222222222222'::uuid])$pg$,'42501','Only distinct, discoverable members can be invited','Duplicate invitations rejected');
select set_config('test.group_room',(select id::text from public.chat_rooms where name='Wandelen'),true);
select set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',true);
select set_config('request.jwt.claims','{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated","is_anonymous":false}',true);
select is((select count(*) from public.chat_messages),0::bigint,'Nonmember cannot read any private or group messages');
select throws_ok(format('insert into public.chat_messages(room_id,user_id,body) values (%L::uuid, auth.uid(), %L)',current_setting('test.group_room'),'Intrusion'),'42501',null,'Nonmember cannot send to group');

set local role anon;
select throws_ok($$select * from public.reports$$,'42501',null,'Unauthenticated reads denied');
select * from finish();
rollback;
